#!/bin/sh
# Run the project's own tests, whatever the stack. The logic lives in tools/testcmd.py:
#   .agents/tests.yaml (yours) > commands.test > .agents/commands/test.sh (yours) > root markers > sub-folders.
#   sh tools/projecttest.sh                run every suite
#   sh tools/projecttest.sh backend ui     only these
#   sh tools/projecttest.sh list           what would run and why; runs nothing
#   sh tools/projecttest.sh init           write .agents/tests.yaml from what was discovered
# Do not edit this file to customize: it is kit-managed and an update overwrites it.
cd "$(dirname "$0")/.."
case "$1" in
  list|init) exec python3 tools/testcmd.py "$@" ;;
  *) exec python3 tools/testcmd.py run "$@" ;;
esac
